-- Point 7 : seed des 445 phrases de test_phrases_complete.json.
-- La métadonnée du fichier annonce 540 phrases ; le tableau "phrases" en contient 445.
-- On importe ce qui existe, sans dédoublonner ni renommer les étiquettes.
-- Copie de référence du fichier (encodage corrigé) : src/data/test_phrases_complete.json
-- Reprise possible à volonté : ON CONFLICT (code) met à jour le contenu du fichier
-- et laisse profession / level_min / level_max / active à la main de l'administration.

ON CONFLICT (code) DO UPDATE SET
  language = EXCLUDED.language,
  category = EXCLUDED.category,
  text_fr = EXCLUDED.text_fr,
  context = EXCLUDED.context,
  is_correction = EXCLUDED.is_correction,
  error_type = EXCLUDED.error_type,
  is_positive = EXCLUDED.is_positive,
  order_index = EXCLUDED.order_index,
  updated_at = now();

-- Rapport d'import journalisé : total, comptage par langue et par catégorie.
SELECT
  'import_test_phrases',
  'test_phrases',
  jsonb_build_object(
    'migration', '20260915081000_test_phrases_seed_complete',
    'point', '7',
    'source', 'test_phrases_complete.json',
    'metadata_total_phrases', 540,
    'file_phrases', 445,
    'rows_total', (SELECT count(*) FROM public.test_phrases),
    'by_language', (
      SELECT coalesce(jsonb_object_agg(language, n), '{}'::jsonb)
      FROM (SELECT language, count(*) AS n FROM public.test_phrases GROUP BY language) s
    ),
    'by_category', (
      SELECT coalesce(jsonb_object_agg(category, n), '{}'::jsonb)
      FROM (SELECT category, count(*) AS n FROM public.test_phrases GROUP BY category) s
    ),
    'corrections', (SELECT count(*) FROM public.test_phrases WHERE is_correction),
    'explanations', (SELECT count(*) FROM public.test_phrases WHERE NOT is_correction),
    'with_context', (SELECT count(*) FROM public.test_phrases WHERE context IS NOT NULL),
    'with_error_type', (SELECT count(*) FROM public.test_phrases WHERE error_type IS NOT NULL)
  );
