  ('EXPR-NL-08', 'NL', 'PRONONCIATION', 'Le "IJ" et "EI" se prononcent comme un "AY" long.', NULL, false, 'IJ/EI', true, 133, true),
  ('EXPR-NL-09', 'NL', 'PRONONCIATION', 'Le "UI" est une diphtongue difficile, proche de "EU" suivi de "I".', NULL, false, 'UI', true, 134, true),
  ('EXPR-NL-10', 'NL', 'PRONONCIATION', 'Les consonnes finales se dévoisent : "hond" se prononce "hont".', NULL, false, 'Dévoisement', true, 135, true),
  ('GRAM-NL-01', 'NL', 'GRAMMAIRE', 'L''ordre des mots est V2 (verbe en 2e position) en phrase principale : "Vandaag ski ik" (Aujourd''hui, je skie).', NULL, false, 'Ordre V2', true, 136, true),
  ('GRAM-NL-02', 'NL', 'GRAMMAIRE', 'L''ordre des mots V2 n''est pas respecté : le verbe doit être en 2e position.', NULL, true, 'Ordre V2', false, 137, true),
  ('GRAM-NL-03', 'NL', 'GRAMMAIRE', 'En subordonnée, le verbe va à la fin : "omdat ik ski" (parce que je skie).', NULL, false, 'Subordonnée', true, 138, true),
  ('GRAM-NL-04', 'NL', 'GRAMMAIRE', 'En subordonnée, vous ne mettez pas le verbe à la fin comme il faut.', NULL, true, 'Subordonnée', false, 139, true),
  ('GRAM-NL-05', 'NL', 'GRAMMAIRE', 'Les verbes séparables : le préfixe va à la fin : "Ik sta op" (je me lève).', NULL, false, 'Verbes séparables', true, 140, true),
  ('GRAM-NL-06', 'NL', 'GRAMMAIRE', 'Les verbes séparables vous posent problème : le préfixe doit aller à la fin.', NULL, true, 'Verbes séparables', false, 141, true),
  ('GRAM-NL-07', 'NL', 'GRAMMAIRE', 'Deux genres : "de" (commun) et "het" (neutre). Il faut les apprendre par cœur.', NULL, false, 'Genres de/het', true, 142, true),
  ('GRAM-NL-08', 'NL', 'GRAMMAIRE', 'Vous mélangez "de" et "het" : apprenez le genre avec chaque nouveau mot.', NULL, true, 'Genres', false, 143, true),
  ('GRAM-NL-09', 'NL', 'GRAMMAIRE', 'L''adjectif prend un "-e" devant les noms définis et pluriels : "de grote berg" mais "een groot huis".', NULL, false, 'Adjectifs', true, 144, true),
  ('GRAM-NL-10', 'NL', 'GRAMMAIRE', 'Le passé composé utilise "hebben" ou "zijn" selon le verbe.', NULL, false, 'Auxiliaires', true, 145, true),
  ('GRAM-NL-11', 'NL', 'GRAMMAIRE', 'Les verbes de mouvement prennent "zijn" : "Ik ben geskied" (j''ai skié).', NULL, false, 'Zijn', true, 146, true),
  ('GRAM-NL-12', 'NL', 'GRAMMAIRE', 'Le diminutif (-je, -tje, -pje, -etje) est très utilisé : "huisje" (maisonnette).', NULL, false, 'Diminutifs', true, 147, true),
  ('GRAM-NL-13', 'NL', 'GRAMMAIRE', '"Er" a plusieurs fonctions (il y a, pronom, lieu) : "Er is sneeuw" (Il y a de la neige).', NULL, false, 'Er', true, 148, true),
  ('GRAM-NL-14', 'NL', 'GRAMMAIRE', 'La négation "niet" se place généralement en fin de phrase ou avant l''élément nié.', NULL, false, 'Négation', true, 149, true),
  ('GRAM-NL-15', 'NL', 'GRAMMAIRE', 'Le placement de "niet" est souvent incorrect dans vos phrases.', NULL, true, 'Négation', false, 150, true),
  ('GRAM-NL-16', 'NL', 'GRAMMAIRE', 'Les prépositions régissent parfois des cas : "met hem" (avec lui) vs "van hem" (de lui).', NULL, false, 'Prépositions', true, 151, true),
  ('TECH-NL-V01', 'NL', 'VOCABULAIRE', 'Rappel : skischool (école de ski), les (cours), beginner (débutant), gevorderde (intermédiaire), expert (confirmé).', 'Niveaux', false, NULL, true, 152, true),
  ('TECH-NL-V02', 'NL', 'VOCABULAIRE', 'Rappel : ploeg/pizzapunt (chasse-neige), parallelle bocht (virage parallèle), stokken (bâtons), kanten (carres).', 'Technique', false, NULL, true, 153, true),
  ('TECH-NL-V03', 'NL', 'VOCABULAIRE', 'Rappel : buig je knieën (pliez les genoux), leun voorover (penchez-vous en avant), gewichtsverplaatsing (transfert de poids).', 'Instructions', false, NULL, true, 154, true),
  ('TECH-NL-V04', 'NL', 'VOCABULAIRE', 'Rappel : stoeltjeslift (télésiège), sleeplift (téléski), gondel/cabine (télécabine).', 'Remontées', false, NULL, true, 155, true),
  ('TECH-NL-V05', 'NL', 'VOCABULAIRE', 'Rappel : veiligheidsbeugel (garde-corps), voetensteun (repose-pieds), omhoog (lever), omlaag (baisser).', 'Remontées', false, NULL, true, 156, true),
  ('TECH-NL-V06', 'NL', 'VOCABULAIRE', 'Rappel : kijk vooruit (regardez devant), volg mij (suivez-moi), stop hier (arrêtez-vous ici), goed gedaan (bien joué).', 'Instructions', false, NULL, true, 157, true),
  ('TECH-NL-V07', 'NL', 'VOCABULAIRE', 'Rappel : skipunten (spatules), skistaarten (talons), bindingen (fixations), skischoenen (chaussures).', 'Équipement', false, NULL, true, 158, true),
  ('TECH-NL-V08', 'NL', 'VOCABULAIRE', 'Rappel : piste (piste), groene piste (piste verte), off-piste (hors-piste), bulten (bosses).', 'Pistes', false, NULL, true, 159, true),
  ('TECH-NL-V09', 'NL', 'VOCABULAIRE', 'Rappel : skigebied (domaine skiable), skiresort (station de ski).', 'Station', false, NULL, true, 160, true),
  ('TECH-NL-V10', 'NL', 'VOCABULAIRE', 'Rappel : Waar doet het pijn? (Où avez-vous mal?), Kun je bewegen? (Pouvez-vous bouger?), Hulp is onderweg (Les secours arrivent).', 'Urgence', false, NULL, true, 161, true),
  ('EXPR-RU-01', 'RU', 'PRONONCIATION', 'Le "Ы" (y) est une voyelle difficile : positionnez la langue comme pour "i" mais reculée.', NULL, false, 'Ы', true, 162, true),
  ('EXPR-RU-02', 'RU', 'PRONONCIATION', 'Le son "Ы" est absent de votre prononciation : c''est un son essentiel en russe.', NULL, true, 'Ы', false, 163, true),
  ('EXPR-RU-03', 'RU', 'PRONONCIATION', 'Distinguez les consonnes dures et molles (palatalisées) : c''est phonémique en russe.', NULL, false, 'Consonnes molles', true, 164, true),
  ('EXPR-RU-04', 'RU', 'PRONONCIATION', 'Vous ne faites pas la différence entre consonnes dures et molles : travaillez ce point.', NULL, true, 'Consonnes molles', false, 165, true),
  ('EXPR-RU-05', 'RU', 'PRONONCIATION', 'Le "Р" russe est roulé comme en espagnol ou italien.', NULL, false, 'R roulé', true, 166, true),
  ('EXPR-RU-06', 'RU', 'PRONONCIATION', 'Le "Х" se prononce comme le "J" espagnol ou le "CH" allemand de "Bach".', NULL, false, 'Х', true, 167, true),
  ('EXPR-RU-07', 'RU', 'PRONONCIATION', 'Les voyelles non accentuées se réduisent : "О" non accentué → "A", "Е/Я" non accentué → "И".', NULL, false, 'Réduction vocalique', true, 168, true),
  ('EXPR-RU-08', 'RU', 'PRONONCIATION', 'L''accent tonique est mobile et distinctif : apprenez-le avec chaque mot.', NULL, false, 'Accent tonique', true, 169, true),
  ('EXPR-RU-09', 'RU', 'PRONONCIATION', 'Le "Щ" se prononce comme un "CH" long et mouillé.', NULL, false, 'Щ', true, 170, true),
  ('EXPR-RU-10', 'RU', 'PRONONCIATION', 'Les consonnes finales se dévoisent : "год" (année) se prononce "got".', NULL, false, 'Dévoisement', true, 171, true),
  ('GRAM-RU-01', 'RU', 'GRAMMAIRE', 'Le russe a 6 cas (nominatif, génitif, datif, accusatif, instrumental, prépositionnel).', NULL, false, 'Cas', true, 172, true),
  ('GRAM-RU-02', 'RU', 'GRAMMAIRE', 'La déclinaison des noms et adjectifs est mal maîtrisée : les cas sont essentiels.', NULL, true, 'Cas', false, 173, true),
  ('GRAM-RU-03', 'RU', 'GRAMMAIRE', 'Les verbes ont deux aspects : imperfectif (action en cours/habituelle) et perfectif (action achevée).', NULL, false, 'Aspects', true, 174, true),
  ('GRAM-RU-04', 'RU', 'GRAMMAIRE', 'Vous confondez les aspects verbaux : imperfectif vs perfectif est fondamental.', NULL, true, 'Aspects', false, 175, true),
  ('GRAM-RU-05', 'RU', 'GRAMMAIRE', 'Le verbe "être" au présent est généralement omis : "Я студент" (Je suis étudiant).', NULL, false, 'Être omis', true, 176, true),
  ('GRAM-RU-06', 'RU', 'GRAMMAIRE', 'Les verbes de mouvement distinguent aller à pied/en véhicule, une fois/habituellement.', NULL, false, 'Verbes mouvement', true, 177, true),
  ('GRAM-RU-07', 'RU', 'GRAMMAIRE', 'Les verbes de mouvement russes sont complexes et mal utilisés.', NULL, true, 'Verbes mouvement', false, 178, true),
  ('GRAM-RU-08', 'RU', 'GRAMMAIRE', 'L''adjectif s''accorde en genre, nombre et cas avec le nom.', NULL, false, 'Accord adjectif', true, 179, true),
  ('GRAM-RU-09', 'RU', 'GRAMMAIRE', 'Après les nombres 2-4, le nom est au génitif singulier ; après 5+, au génitif pluriel.', NULL, false, 'Nombres + cas', true, 180, true),
  ('GRAM-RU-10', 'RU', 'GRAMMAIRE', 'L''accord après les nombres vous pose problème : révisez les règles.', NULL, true, 'Nombres', false, 181, true),
  ('GRAM-RU-11', 'RU', 'GRAMMAIRE', 'Les prépositions régissent des cas spécifiques : "в" + accusatif (direction) vs "в" + prépositionnel (lieu).', NULL, false, 'Prépositions', true, 182, true),
  ('GRAM-RU-12', 'RU', 'GRAMMAIRE', 'Le passé s''accorde en genre avec le sujet : "он читал" (il lisait) vs "она читала" (elle lisait).', NULL, false, 'Passé + genre', true, 183, true),
  ('GRAM-RU-13', 'RU', 'GRAMMAIRE', 'L''ordre des mots est relativement libre grâce aux cas, mais l''information nouvelle va en fin.', NULL, false, 'Ordre des mots', true, 184, true),
  ('GRAM-RU-14', 'RU', 'GRAMMAIRE', '"У меня есть" (j''ai) : littéralement "chez moi il y a" - structure à mémoriser.', NULL, false, 'Avoir', true, 185, true),
  ('GRAM-RU-15', 'RU', 'GRAMMAIRE', 'La négation "не" se place directement avant le verbe ou l''élément nié.', NULL, false, 'Négation', true, 186, true),
  ('GRAM-RU-16', 'RU', 'GRAMMAIRE', 'Le génitif s''utilise après la négation : "У меня нет машины" (je n''ai pas de voiture).', NULL, false, 'Génitif + négation', true, 187, true),
  ('TECH-RU-V01', 'RU', 'VOCABULAIRE', 'Rappel : горнолыжная школа (école de ski), урок (cours), начинающий (débutant), средний уровень (intermédiaire), продвинутый (confirmé).', 'Niveaux', false, NULL, true, 188, true),
  ('TECH-RU-V02', 'RU', 'VOCABULAIRE', 'Rappel : плуг (chasse-neige), параллельный поворот (virage parallèle), палки (bâtons), канты (carres).', 'Technique', false, NULL, true, 189, true),
  ('TECH-RU-V03', 'RU', 'VOCABULAIRE', 'Rappel : согните колени (pliez les genoux), наклонитесь вперёд (penchez-vous en avant), перенос веса (transfert de poids).', 'Instructions', false, NULL, true, 190, true),
  ('TECH-RU-V04', 'RU', 'VOCABULAIRE', 'Rappel : кресельный подъёмник (télésiège), бугельный подъёмник (téléski), гондола (télécabine).', 'Remontées', false, NULL, true, 191, true),
  ('TECH-RU-V05', 'RU', 'VOCABULAIRE', 'Rappel : страховочная дуга (garde-corps), подножка (repose-pieds), поднять (lever), опустить (baisser).', 'Remontées', false, NULL, true, 192, true),
  ('TECH-RU-V06', 'RU', 'VOCABULAIRE', 'Rappel : смотрите вперёд (regardez devant), следуйте за мной (suivez-moi), остановитесь здесь (arrêtez-vous ici), молодец (bien joué).', 'Instructions', false, NULL, true, 193, true),
  ('TECH-RU-V07', 'RU', 'VOCABULAIRE', 'Rappel : носки лыж (spatules), пятки лыж (talons), крепления (fixations), ботинки (chaussures).', 'Équipement', false, NULL, true, 194, true),
  ('TECH-RU-V08', 'RU', 'VOCABULAIRE', 'Rappel : трасса/склон (piste), зелёная трасса (piste verte), внетрассовое катание (hors-piste), бугры (bosses).', 'Pistes', false, NULL, true, 195, true),
  ('TECH-RU-V09', 'RU', 'VOCABULAIRE', 'Rappel : горнолыжный курорт (station de ski).', 'Station', false, NULL, true, 196, true),
  ('TECH-RU-V10', 'RU', 'VOCABULAIRE', 'Rappel : Где болит? (Où avez-vous mal?), Вы можете двигаться? (Pouvez-vous bouger?), Помощь идёт (Les secours arrivent).', 'Urgence', false, NULL, true, 197, true),
  ('EXPR-IT-01', 'IT', 'PRONONCIATION', 'Les consonnes doubles sont plus longues : "palla" ≠ "pala". Marquez bien la durée.', NULL, false, 'Doubles', true, 198, true),
