  ('EXPR-IT-04', 'IT', 'PRONONCIATION', 'Le "GLI" se prononce comme le "LL" espagnol ou le "LH" portugais (mouillé).', NULL, false, 'GLI', true, 201, true),
  ('EXPR-IT-05', 'IT', 'PRONONCIATION', 'Le "GN" se prononce comme en français ("montagne").', NULL, false, 'GN', true, 202, true),
