  ('EXPR-IT-10', 'IT', 'PRONONCIATION', 'L''accent tonique varie : apprenez-le avec chaque mot.', NULL, false, 'Accent tonique', true, 207, true),
  ('GRAM-IT-01', 'IT', 'GRAMMAIRE', 'Le sujet est généralement omis : "Parlo italiano" (pas "Io parlo italiano").', NULL, false, 'Sujet omis', true, 208, true),
  ('GRAM-IT-02', 'IT', 'GRAMMAIRE', 'Les articles définis : il/lo/la/i/gli/le - "lo" devant s+consonne, z, gn, ps, x.', NULL, false, 'Articles', true, 209, true),
  ('GRAM-IT-03', 'IT', 'GRAMMAIRE', 'Vous utilisez mal les articles "il" et "lo" : révisez les règles.', NULL, true, 'Articles', false, 210, true),
  ('GRAM-IT-04', 'IT', 'GRAMMAIRE', 'Les articles contractés : a+il=al, di+il=del, in+il=nel, etc.', NULL, false, 'Contractions', true, 211, true),
  ('GRAM-IT-05', 'IT', 'GRAMMAIRE', 'Passato prossimo vs imperfetto : comme en français, mais l''imparfait est plus utilisé en italien.', NULL, false, 'Passé', true, 212, true),
