  ('GRAM-IT-09', 'IT', 'GRAMMAIRE', '"Piacere" fonctionne comme "gustar" espagnol : "Mi piace lo sci" (le ski me plaît).', NULL, false, 'Piacere', true, 216, true),
  ('GRAM-IT-10', 'IT', 'GRAMMAIRE', 'La structure de PIACERE vous pose problème : le sujet français devient COI.', NULL, true, 'Piacere', false, 217, true),
  ('GRAM-IT-11', 'IT', 'GRAMMAIRE', 'Le subjonctif est très utilisé après "che", "penso che", "voglio che", etc.', NULL, false, 'Subjonctif', true, 218, true),
  ('GRAM-IT-12', 'IT', 'GRAMMAIRE', 'Le subjonctif italien est mal maîtrisé : il est plus fréquent qu''en français moderne.', NULL, true, 'Subjonctif', false, 219, true),
