  ('GRAM-IT-19', 'IT', 'GRAMMAIRE', 'Attention aux faux amis : "camera" = chambre (pas caméra), "salire" = monter (pas salir).', NULL, false, 'Faux amis', true, 226, true),
  ('TECH-IT-V01', 'IT', 'VOCABULAIRE', 'Rappel : scuola di sci (école de ski), lezione (cours), principiante (débutant), intermedio (intermédiaire), esperto (confirmé).', 'Niveaux', false, NULL, true, 227, true),
  ('TECH-IT-V02', 'IT', 'VOCABULAIRE', 'Rappel : spazzaneve (chasse-neige), curva parallela (virage parallèle), bastoncini (bâtons), lamine (carres).', 'Technique', false, NULL, true, 228, true),
  ('TECH-IT-V03', 'IT', 'VOCABULAIRE', 'Rappel : piega le ginocchia (pliez les genoux), piegati in avanti (penchez-vous en avant), trasferimento del peso (transfert de poids).', 'Instructions', false, NULL, true, 229, true),
