  ('EXPR-ZH-01', 'ZH', 'PRONONCIATION', 'Les 4 tons sont essentiels en chinois : un mauvais ton = un autre mot. Pratiquez-les systématiquement.', NULL, false, 'Tons', true, 237, true),
