  ('EXPR-ZH-03', 'ZH', 'PRONONCIATION', 'Le 3ème ton descend puis remonte ; le 4ème ton descend brusquement.', NULL, false, 'Tons 3 et 4', true, 239, true),
  ('EXPR-ZH-04', 'ZH', 'PRONONCIATION', 'Le "X" (pinyin) se prononce comme un "S" chuinté, langue derrière les dents.', NULL, false, 'X', true, 240, true),
