  ('EXPR-ZH-07', 'ZH', 'PRONONCIATION', 'Le "R" chinois est une approximante rétroflexe, différente du R français.', NULL, false, 'R', true, 243, true),
  ('EXPR-ZH-08', 'ZH', 'PRONONCIATION', 'Distinguez les consonnes aspirées (p, t, k, c, ch, q) des non-aspirées (b, d, g, z, zh, j).', NULL, false, 'Aspiration', true, 244, true),
  ('EXPR-ZH-09', 'ZH', 'PRONONCIATION', 'Vous ne faites pas la différence entre consonnes aspirées et non-aspirées.', NULL, true, 'Aspiration', false, 245, true),
  ('EXPR-ZH-10', 'ZH', 'PRONONCIATION', 'Le "Ü" (pinyin) est comme le "u" français, mais le "U" simple est plus postérieur.', NULL, false, 'Ü vs U', true, 246, true),
  ('GRAM-ZH-01', 'ZH', 'GRAMMAIRE', 'Le chinois n''a pas de conjugaison : le verbe reste invariable (我滑雪 wǒ huáxuě = je skie).', NULL, false, 'Pas de conjugaison', true, 247, true),
  ('GRAM-ZH-02', 'ZH', 'GRAMMAIRE', 'L''ordre des mots est Sujet + Temps + Lieu + Verbe + Objet.', NULL, false, 'Ordre des mots', true, 248, true),
  ('GRAM-ZH-03', 'ZH', 'GRAMMAIRE', 'L''ordre des mots chinois est différent du français : le temps et le lieu vont AVANT le verbe.', NULL, true, 'Ordre des mots', false, 249, true),
  ('GRAM-ZH-04', 'ZH', 'GRAMMAIRE', 'Les classificateurs (量词) sont obligatoires entre nombre/démonstratif et nom : 一个人 yī gè rén (une personne).', NULL, false, 'Classificateurs', true, 250, true),
  ('GRAM-ZH-05', 'ZH', 'GRAMMAIRE', 'Les classificateurs sont souvent oubliés ou mal choisis.', NULL, true, 'Classificateurs', false, 251, true),
  ('GRAM-ZH-06', 'ZH', 'GRAMMAIRE', 'Le passé se marque avec 了 (le) après le verbe pour l''action accomplie : 我滑了雪 (j''ai skié).', NULL, false, '了 (le)', true, 252, true),
  ('GRAM-ZH-07', 'ZH', 'GRAMMAIRE', 'L''action en cours se marque avec 在 (zài) avant le verbe : 我在滑雪 (je suis en train de skier).', NULL, false, '在 (zài)', true, 253, true),
  ('GRAM-ZH-08', 'ZH', 'GRAMMAIRE', 'L''expérience passée se marque avec 过 (guò) : 我滑过雪 (j''ai déjà skié dans ma vie).', NULL, false, '过 (guò)', true, 254, true),
  ('GRAM-ZH-09', 'ZH', 'GRAMMAIRE', 'Vous confondez 了, 过 et 在 : ce sont trois aspects différents.', NULL, true, 'Aspects', false, 255, true),
  ('GRAM-ZH-10', 'ZH', 'GRAMMAIRE', 'La négation au présent : 不 (bù) ; la négation au passé : 没 (méi).', NULL, false, 'Négation', true, 256, true),
  ('GRAM-ZH-11', 'ZH', 'GRAMMAIRE', 'Vous utilisez 不 au lieu de 没 pour les actions passées.', NULL, true, '不 vs 没', false, 257, true),
