  ('GRAM-ZH-13', 'ZH', 'GRAMMAIRE', 'Le complément de résultat se place après le verbe : 学会 (xuéhuì) = apprendre jusqu''à savoir.', NULL, false, 'Compléments', true, 259, true),
  ('GRAM-ZH-14', 'ZH', 'GRAMMAIRE', 'Le comparatif : A 比 B + adjectif (A bǐ B = A est plus... que B).', NULL, false, 'Comparatif', true, 260, true),
  ('GRAM-ZH-15', 'ZH', 'GRAMMAIRE', '"Il y a" = 有 (yǒu) : 这里有雪 (zhèlǐ yǒu xuě = il y a de la neige ici).', NULL, false, '有 (yǒu)', true, 261, true),
  ('GRAM-ZH-16', 'ZH', 'GRAMMAIRE', 'Le thème se place souvent en début de phrase : 滑雪，我很喜欢 (Le ski, j''aime beaucoup).', NULL, false, 'Thématisation', true, 262, true),
  ('TECH-ZH-V01', 'ZH', 'VOCABULAIRE', 'Rappel : 滑雪学校 huáxuě xuéxiào (école de ski), 课 kè (cours), 初学者 chūxuézhě (débutant), 中级 zhōngjí (intermédiaire), 高级 gāojí (confirmé).', 'Niveaux', false, NULL, true, 263, true),
  ('TECH-ZH-V02', 'ZH', 'VOCABULAIRE', 'Rappel : 犁式 lí shì (chasse-neige), 平行转弯 píngxíng zhuǎnwān (virage parallèle), 雪杖 xuězhàng (bâtons), 雪板边刃 xuěbǎn biānrèn (carres).', 'Technique', false, NULL, true, 264, true),
  ('TECH-ZH-V03', 'ZH', 'VOCABULAIRE', 'Rappel : 弯曲膝盖 wānqū xīgài (pliez les genoux), 身体前倾 shēntǐ qiánqīng (penchez-vous en avant).', 'Instructions', false, NULL, true, 265, true),
  ('TECH-ZH-V04', 'ZH', 'VOCABULAIRE', 'Rappel : 缆车 lǎnchē (télésiège/télécabine), 拖牵 tuōqiān (téléski).', 'Remontées', false, NULL, true, 266, true),
  ('TECH-ZH-V05', 'ZH', 'VOCABULAIRE', 'Rappel : 安全杆 ānquán gǎn (garde-corps), 抬起 táiqǐ (lever), 放下 fàngxià (baisser).', 'Remontées', false, NULL, true, 267, true),
  ('TECH-ZH-V06', 'ZH', 'VOCABULAIRE', 'Rappel : 向前看 xiàng qián kàn (regardez devant), 跟我来 gēn wǒ lái (suivez-moi), 在这里停 zài zhèlǐ tíng (arrêtez-vous ici), 很好 hěn hǎo (bien joué).', 'Instructions', false, NULL, true, 268, true),
  ('TECH-ZH-V07', 'ZH', 'VOCABULAIRE', 'Rappel : 雪板头 xuěbǎn tóu (spatules), 雪板尾 xuěbǎn wěi (talons), 固定器 gùdìngqì (fixations), 雪鞋 xuěxié (chaussures).', 'Équipement', false, NULL, true, 269, true),
  ('TECH-ZH-V08', 'ZH', 'VOCABULAIRE', 'Rappel : 雪道 xuědào (piste), 绿道 lǜdào (piste verte), 野雪 yě xuě (hors-piste).', 'Pistes', false, NULL, true, 270, true),
  ('TECH-ZH-V09', 'ZH', 'VOCABULAIRE', 'Rappel : 滑雪场 huáxuěchǎng (station de ski).', 'Station', false, NULL, true, 271, true),
  ('TECH-ZH-V10', 'ZH', 'VOCABULAIRE', 'Rappel : 哪里疼？nǎlǐ téng? (Où avez-vous mal?), 你能动吗？nǐ néng dòng ma? (Pouvez-vous bouger?), 救援马上到 jiùyuán mǎshàng dào (Les secours arrivent).', 'Urgence', false, NULL, true, 272, true),
