  ('EXPR-EN-10', 'EN', 'PRONONCIATION', 'L''accent tonique est souvent mal placé dans vos mots.', NULL, true, 'Accent tonique', false, 373, true),
  ('EXPR-EN-11', 'EN', 'PRONONCIATION', 'Les consonnes finales sont souvent avalées en anglais : "last" peut sonner "las''".', NULL, false, 'Consonnes finales', true, 374, true),
  ('EXPR-EN-12', 'EN', 'PRONONCIATION', 'Attention à l''intonation anglaise qui monte et descend différemment du français.', NULL, false, 'Intonation', true, 375, true),
  ('GRAM-EN-01', 'EN', 'GRAMMAIRE', 'Les articles "a/an/the" sont souvent mal utilisés par les francophones.', NULL, false, 'Articles', true, 376, true),
  ('GRAM-EN-02', 'EN', 'GRAMMAIRE', 'L''utilisation des articles est incorrecte : révisez a/an/the.', NULL, true, 'Articles', false, 377, true),
  ('GRAM-EN-03', 'EN', 'GRAMMAIRE', 'L''ordre des mots est SVO en anglais, comme en français.', NULL, false, 'Ordre SVO', true, 378, true),
  ('GRAM-EN-04', 'EN', 'GRAMMAIRE', 'L''adjectif se place AVANT le nom en anglais : "a big mountain", pas "a mountain big".', NULL, false, 'Adjectif', true, 379, true),
  ('GRAM-EN-05', 'EN', 'GRAMMAIRE', 'Vous placez l''adjectif après le nom comme en français : en anglais, il va avant.', NULL, true, 'Adjectif', false, 380, true),
  ('GRAM-EN-06', 'EN', 'GRAMMAIRE', 'Le présent simple vs présent continu : "I ski" (habitude) vs "I am skiing" (maintenant).', NULL, false, 'Present simple/continu', true, 381, true),
  ('GRAM-EN-07', 'EN', 'GRAMMAIRE', 'Vous confondez le présent simple et le présent continu.', NULL, true, 'Present simple/continu', false, 382, true),
  ('GRAM-EN-08', 'EN', 'GRAMMAIRE', 'Le present perfect exprime un lien avec le présent : "I have skied" (expérience de vie).', NULL, false, 'Present perfect', true, 383, true),
  ('GRAM-EN-09', 'EN', 'GRAMMAIRE', 'Vous utilisez mal le present perfect : il n''équivaut pas exactement au passé composé.', NULL, true, 'Present perfect', false, 384, true),
  ('GRAM-EN-10', 'EN', 'GRAMMAIRE', 'Les prépositions de lieu : "at" (point), "in" (espace fermé), "on" (surface).', NULL, false, 'Prépositions', true, 385, true),
  ('GRAM-EN-11', 'EN', 'GRAMMAIRE', 'Les prépositions sont souvent incorrectes : elles diffèrent du français.', NULL, true, 'Prépositions', false, 386, true),
  ('GRAM-EN-12', 'EN', 'GRAMMAIRE', 'Les modaux (can, must, should, will) ne prennent pas de "to" : "I can ski", pas "I can to ski".', NULL, false, 'Modaux', true, 387, true),
  ('GRAM-EN-13', 'EN', 'GRAMMAIRE', 'Vous ajoutez "to" après les modaux : c''est incorrect.', NULL, true, 'Modaux', false, 388, true),
  ('GRAM-EN-14', 'EN', 'GRAMMAIRE', 'Le génitif (''s) exprime la possession : "the student''s skis" = les skis de l''élève.', NULL, false, 'Génitif', true, 389, true),
  ('GRAM-EN-15', 'EN', 'GRAMMAIRE', 'Le conditionnel : "If + past simple, would + infinitif" : "If I had time, I would ski".', NULL, false, 'Conditionnel', true, 390, true),
  ('GRAM-EN-16', 'EN', 'GRAMMAIRE', 'La structure conditionnelle est incorrecte : révisez les "if clauses".', NULL, true, 'Conditionnel', false, 391, true),
  ('GRAM-EN-17', 'EN', 'GRAMMAIRE', '"Some" (affirmatif) vs "any" (négatif/interrogatif) : "I have some skis" / "Do you have any skis?"', NULL, false, 'Some/Any', true, 392, true),
  ('GRAM-EN-18', 'EN', 'GRAMMAIRE', 'La distinction some/any n''est pas respectée.', NULL, true, 'Some/Any', false, 393, true),
  ('GRAM-EN-19', 'EN', 'GRAMMAIRE', 'Les phrasal verbs sont nombreux : "put on" (enfiler), "take off" (enlever), "slow down" (ralentir).', NULL, false, 'Phrasal verbs', true, 394, true),
  ('GRAM-EN-20', 'EN', 'GRAMMAIRE', 'Les phrasal verbs sont mal utilisés ou évités.', NULL, true, 'Phrasal verbs', false, 395, true),
  ('GRAM-EN-21', 'EN', 'GRAMMAIRE', '"For" (durée) vs "since" (point de départ) : "for 5 years" / "since 2019".', NULL, false, 'For/Since', true, 396, true),
  ('GRAM-EN-22', 'EN', 'GRAMMAIRE', 'Vous confondez "for" et "since".', NULL, true, 'For/Since', false, 397, true),
  ('GRAM-EN-23', 'EN', 'GRAMMAIRE', 'Le passif : "The lesson is given by..." (La leçon est donnée par...).', NULL, false, 'Passif', true, 398, true),
  ('GRAM-EN-24', 'EN', 'GRAMMAIRE', 'La formation du passif est incorrecte.', NULL, true, 'Passif', false, 399, true),
  ('GRAM-EN-25', 'EN', 'GRAMMAIRE', 'Le discours indirect : "He said he would come" (Il a dit qu''il viendrait).', NULL, false, 'Discours indirect', true, 400, true),
  ('GRAM-EN-26', 'EN', 'GRAMMAIRE', 'Le discours indirect est mal formé : attention au "backshift".', NULL, true, 'Discours indirect', false, 401, true),
  ('GRAM-EN-27', 'EN', 'GRAMMAIRE', '"Make" vs "do" : "make a decision" mais "do an exercise".', NULL, false, 'Make/Do', true, 402, true),
